class Solution {
public:
    int mincostTickets(vector<int>& days, vector<int>& costs) {
        unordered_set<int> travelDays(days.begin(), days.end());
        int lastDay = days.back();
        vector<int> dp(lastDay + 1, 0);
        for (int d = 1; d <= lastDay; ++d) {
            if (!travelDays.count(d)) {
                dp[d] = dp[d - 1];
            } else {
                int c1 = dp[max(0, d - 1)] + costs[0];
                int c7 = dp[max(0, d - 7)] + costs[1];
                int c30 = dp[max(0, d - 30)] + costs[2];
                dp[d] = min({c1, c7, c30});
            }
        }
        return dp[lastDay];
    }
};

class Solution {
    public int mincostTickets(int[] days, int[] costs) {
        Set<Integer> travelDays = new HashSet<>();
        for (int d : days) travelDays.add(d);
        int lastDay = days[days.length - 1];
        int[] dp = new int[lastDay + 1];
        for (int d = 1; d <= lastDay; d++) {
            if (!travelDays.contains(d)) {
                dp[d] = dp[d - 1];
            } else {
                int c1 = dp[Math.max(0, d - 1)] + costs[0];
                int c7 = dp[Math.max(0, d - 7)] + costs[1];
                int c30 = dp[Math.max(0, d - 30)] + costs[2];
                dp[d] = Math.min(c1, Math.min(c7, c30));
            }
        }
        return dp[lastDay];
    }
}

var mincostTickets = function(days, costs) {
    const travelDays = new Set(days);
    const lastDay = days[days.length - 1];
    const dp = new Array(lastDay + 1).fill(0);
    for (let d = 1; d <= lastDay; d++) {
        if (!travelDays.has(d)) {
            dp[d] = dp[d - 1];
        } else {
            const c1 = dp[Math.max(0, d - 1)] + costs[0];
            const c7 = dp[Math.max(0, d - 7)] + costs[1];
            const c30 = dp[Math.max(0, d - 30)] + costs[2];
            dp[d] = Math.min(c1, c7, c30);
        }
    }
    return dp[lastDay];
};
